import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.CqGPl1zp.js";const c=JSON.parse('{"title":"设备接入（UDP 协议）","description":"","frontmatter":{},"headers":[],"relativePath":"iot/protocol-udp.md","filePath":"iot/protocol-udp.md","lastUpdated":null}'),n={name:"iot/protocol-udp.md"};function d(h,s,l,o,p,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="设备接入-udp-协议" tabindex="-1">设备接入（UDP 协议） <a class="header-anchor" href="#设备接入-udp-协议" aria-label="Permalink to &quot;设备接入（UDP 协议）&quot;">​</a></h1><p>推荐阅读：</p><ul><li><a href="./protocol-overview">《设备接入（概述）》</a> — 建议先阅读，了解整体架构和消息格式</li></ul><p>UDP 协议接入，由 <code>yudao-module-iot-gateway</code> 模块的 <code>protocol.udp</code> 包实现，基于 Vert.x UDP Server，默认端口 8093。</p><p>UDP 是<strong>无连接</strong>协议，仅支持<strong>上行</strong>（设备 → 平台），无法下行推送。每个数据报相互独立，因此采用 <strong>JWT Token</strong> 进行无状态认证。</p><h2 id="_1-整体架构" tabindex="-1">1. 整体架构 <a class="header-anchor" href="#_1-整体架构" aria-label="Permalink to &quot;1. 整体架构&quot;">​</a></h2><h3 id="_1-1-认证方式" tabindex="-1">1.1 认证方式 <a class="header-anchor" href="#_1-1-认证方式" aria-label="Permalink to &quot;1.1 认证方式&quot;">​</a></h3><p>UDP 是无连接的协议，每次请求相互独立。认证流程：</p><ol><li>设备发送 <code>auth</code> 请求，携带 <code>clientId</code>、<code>username</code>、<code>password</code></li><li>网关验证成功后返回 <strong>JWT Token</strong></li><li>后续每次请求在 <code>params</code> 中携带该 Token</li></ol><p>认证由 IotUdpUpstreamHandler 处理。</p><h3 id="_1-2-token-包装格式" tabindex="-1">1.2 Token 包装格式 <a class="header-anchor" href="#_1-2-token-包装格式" aria-label="Permalink to &quot;1.2 Token 包装格式&quot;">​</a></h3><p>认证成功后，后续请求的 <code>params</code> 需要使用以下包装格式：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eyJhbGciOiJIUzI1NiIs...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;body&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 实际请求参数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>token</code>：JWT 令牌，从认证接口获取</li><li><code>body</code>：实际的业务请求参数</li></ul><h3 id="_1-3-消息格式" tabindex="-1">1.3 消息格式 <a class="header-anchor" href="#_1-3-消息格式" aria-label="Permalink to &quot;1.3 消息格式&quot;">​</a></h3><p>UDP 消息统一使用 IotDeviceMessage 对象，通过 IotMessageSerializer 进行序列化/反序列化。序列化方式通过 <code>serialize</code> 配置项指定，详见 <a href="./protocol-overview">《设备接入（概述）》</a> 的「4.3 消息序列化」章节。</p><p>消息的 <code>method</code> 字段标识操作类型：</p><table tabindex="0"><thead><tr><th>method</th><th>说明</th><th>是否需要先认证</th></tr></thead><tbody><tr><td><code>auth</code></td><td>设备认证</td><td>否</td></tr><tr><td><code>thing.auth.register</code></td><td>设备动态注册（一型一密），详见 <a href="./device-register">《设备动态注册》</a></td><td>否</td></tr><tr><td><code>thing.property.post</code></td><td>属性上报</td><td>是</td></tr><tr><td><code>thing.event.post</code></td><td>事件上报</td><td>是</td></tr></tbody></table><p>所有上行消息由 IotUdpUpstreamHandler 统一处理，内部按 <code>method</code> 路由到不同方法：</p><table tabindex="0"><thead><tr><th>method</th><th>处理方法</th><th>说明</th></tr></thead><tbody><tr><td><code>auth</code></td><td><code>#handleAuthenticationRequest(...)</code></td><td>校验三元组，返回 JWT Token，创建会话</td></tr><tr><td><code>thing.auth.register</code></td><td><code>#handleRegisterRequest(...)</code></td><td>一型一密动态注册，返回 deviceSecret</td></tr><tr><td>其它业务方法</td><td><code>#handleBusinessRequest(...)</code></td><td>校验 Token 有效性，转发到消息总线</td></tr></tbody></table><h3 id="_1-4-会话管理" tabindex="-1">1.4 会话管理 <a class="header-anchor" href="#_1-4-会话管理" aria-label="Permalink to &quot;1.4 会话管理&quot;">​</a></h3><p>UDP 虽然是无连接协议，但网关仍会维护一个<strong>会话缓存</strong>（基于 Guava Cache），用于追踪设备状态。</p><p>会话通过 IotUdpSessionManager 管理，使用 <code>expireAfterAccess</code> 策略自动过期清理。</p><h2 id="_2-配置说明" tabindex="-1">2. 配置说明 <a class="header-anchor" href="#_2-配置说明" aria-label="Permalink to &quot;2. 配置说明&quot;">​</a></h2><p>在<strong>网关</strong>的 <code>application.yaml</code> 的 <code>yudao.iot.gateway.protocols</code> 中配置 UDP 协议实例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  iot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      protocols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">udp-json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 是否启用</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">udp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 协议类型</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8093</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 监听端口</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          serialize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 序列化方式</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          udp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            max-sessions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 最大会话数（默认 1000）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            session-timeout-ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 会话超时时间（毫秒，默认 60000）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            receive-buffer-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65536</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 接收缓冲区大小（字节，默认 65536）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            send-buffer-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65536</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 发送缓冲区大小（字节，默认 65536）</span></span></code></pre></div><p>对应 IotGatewayProperties.ProtocolProperties 通用配置类、和 IotUdpConfig 专属配置类。</p><blockquote><p>注意：测试前需确保 <code>enabled</code> 设置为 <code>true</code>，否则协议不会启动。</p></blockquote><h2 id="_3-快速测试【推荐】" tabindex="-1">3. 快速测试【推荐】 <a class="header-anchor" href="#_3-快速测试【推荐】" aria-label="Permalink to &quot;3. 快速测试【推荐】&quot;">​</a></h2><p>可以通过以下集成测试类快速体验，具体步骤见各类的注释：</p><table tabindex="0"><thead><tr><th>设备类型</th><th>测试类</th></tr></thead><tbody><tr><td>直连设备</td><td>IotDirectDeviceUdpProtocolIntegrationTest</td></tr><tr><td>网关设备</td><td>IotGatewayDeviceUdpProtocolIntegrationTest</td></tr><tr><td>网关子设备</td><td>IotGatewaySubDeviceUdpProtocolIntegrationTest</td></tr></tbody></table><h2 id="_4-手工测试-直连设备" tabindex="-1">4. 手工测试（直连设备） <a class="header-anchor" href="#_4-手工测试-直连设备" aria-label="Permalink to &quot;4. 手工测试（直连设备）&quot;">​</a></h2><p>UDP 没有类似 Postman、curl 这样开箱即用的调试工具，因此暂不提供手工测试案例。<strong>请使用第 3 节的集成测试类进行测试</strong>，它已经封装好了序列化和 Token 包装逻辑。</p>`,33)])])}const E=a(n,[["render",d]]);export{c as __pageData,E as default};
